import networkx as nx

def solve_for_n(n):
    black_squares = []
    for i in range(n):
        for j in range(n):
            if (i + j) % 2 == 0:
                black_squares.append((i, j))

    G = nx.Graph()
    for i in range(len(black_squares)):
        for j in range(i + 1, len(black_squares)):
            b1 = black_squares[i]
            b2 = black_squares[j]
            if abs(b1[0] - b2[0]) == 1 and abs(b1[1] - b2[1]) == 1:
                G.add_edge(b1, b2)

    matching = nx.max_weight_matching(G, maxcardinality=True)
    # matching is a set of edges, but the edges are pairs in the matching.
    # The size of the matching is the number of pairs.
    m_size = len(matching)
    n_b = len(black_squares)
    return n_b - m_size

for n in range(1, 7):
    print(f"n={n}, min_trominoes={solve_for_n(n)}")
